function largest1BorderedSquare(grid) {
  const rows = grid.length;
  const cols = grid[0].length;
  const left = Array.from({ length: rows + 1 }, () => new Array(cols + 1).fill(0));
  const up = Array.from({ length: rows + 1 }, () => new Array(cols + 1).fill(0));
  let best = 0;

  for (let i = 1; i <= rows; i++) {
    for (let j = 1; j <= cols; j++) {
      if (grid[i - 1][j - 1] === 0) {
        continue;
      }
      left[i][j] = left[i][j - 1] + 1;
      up[i][j] = up[i - 1][j] + 1;
      let side = Math.min(left[i][j], up[i][j]);
      while (side > best) {
        const topRow = left[i - side + 1][j];
        const leftColumn = up[i][j - side + 1];
        if (topRow >= side && leftColumn >= side) {
          best = side;
        }
        side--;
      }
    }
  }
  return best * best;
}

