function largest1BorderedSquare(grid) {
  const rows = grid.length, cols = grid[0].length;
  let best = 0;
  for (let r = 0; r < rows; r++)
    for (let c = 0; c < cols; c++)
      for (let k = 1; r + k <= rows && c + k <= cols; k++) {
        let ok = true;
        for (let t = 0; t < k && ok; t++) {
          if (grid[r][c + t] !== 1 || grid[r + k - 1][c + t] !== 1) ok = false;
          if (grid[r + t][c] !== 1 || grid[r + t][c + k - 1] !== 1) ok = false;
        }
        if (ok) best = Math.max(best, k * k);
      }
  return best;
}

