function generate(rand, size) {
  const rows = size === 'large' ? 60 + Math.floor(rand() * 41) : 1 + Math.floor(rand() * 6);
  const cols = size === 'large' ? 60 + Math.floor(rand() * 41) : 1 + Math.floor(rand() * 6);
  const density = size === 'large' ? 0.85 + rand() * 0.14 : rand();
  const grid = Array.from({ length: rows }, () => Array.from({ length: cols }, () => (rand() < density ? 1 : 0)));
  // Draw a few hollow square borders so large answers appear.
  const frames = size === 'large' ? 3 : Math.floor(rand() * 2);
  for (let f = 0; f < frames; f++) {
    const k = 1 + Math.floor(rand() * Math.min(rows, cols));
    const r = Math.floor(rand() * (rows - k + 1));
    const c = Math.floor(rand() * (cols - k + 1));
    for (let t = 0; t < k; t++) {
      grid[r][c + t] = 1;
      grid[r + k - 1][c + t] = 1;
      grid[r + t][c] = 1;
      grid[r + t][c + k - 1] = 1;
    }
    // Sometimes break one border cell so a near-miss square is present.
    if (rand() < 0.5 && k > 2) grid[r][c + 1 + Math.floor(rand() * (k - 2))] = 0;
  }
  return [grid];
}
